#!/usr/bin/env python3
"""Verify the bundled relay-release RPC using generated bytes and loopback peers.

Never reads the app's queue, credentials, torrent metadata or download folders.
"""
import argparse
import base64
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import secrets
import socket
import struct
import subprocess
import tempfile
import threading
import time
import urllib.request
import urllib.error

from importlib.util import spec_from_file_location, module_from_spec
_fixture_spec = spec_from_file_location("fixtures", Path(__file__).with_name("test-local-torrents.py"))
fixtures = module_from_spec(_fixture_spec)
_fixture_spec.loader.exec_module(fixtures)

PIECE = 16384
SIZES = [24576, 24576, 24576, 2 * 1024 * 1024 + 8192]
DATA = [hashlib.shake_256(f"live-cleanup-fixture-{i}".encode()).digest(n) for i, n in enumerate(SIZES)]
PAYLOAD = b"".join(DATA)
COUNT = (len(PAYLOAD) + PIECE - 1) // PIECE


def wait_for(predicate, label, seconds=30):
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        result = predicate()
        if result:
            return result
        time.sleep(0.1)
    raise AssertionError(f"Timed out: {label}")


def receive(sock, count):
    result = b""
    while len(result) < count:
        chunk = sock.recv(count - len(result))
        if not chunk:
            raise EOFError()
        result += chunk
    return result


def frame(kind, data=b""):
    return struct.pack("!I", 1 + len(data)) + bytes([kind]) + data


def handshake(info_hash, peer_id):
    return b"\x13BitTorrent protocol" + b"\x00" * 7 + b"\x04" + info_hash + peer_id


class Seeder:
    def __init__(self):
        self.sock = socket.socket()
        self.sock.bind(("127.0.0.1", 0))
        self.sock.listen()
        self.port = self.sock.getsockname()[1]
        self.connections = 0
        self.disconnections = 0
        self.allowed = {0, 1}
        self.clients = []
        self.lock = threading.RLock()
        self.errors = []

    def start(self, info_hash):
        self.info_hash = info_hash
        threading.Thread(target=self.accept, daemon=True).start()

    def accept(self):
        while True:
            try:
                client, _ = self.sock.accept()
            except OSError:
                return
            threading.Thread(target=self.serve, args=(client,), daemon=True).start()

    def serve(self, client):
        try:
            client.settimeout(40)
            incoming = receive(client, 68)
            if incoming[:20] != b"\x13BitTorrent protocol":
                return  # Decline encryption negotiation; this fixture speaks plaintext.
            assert incoming[28:48] == self.info_hash, "Unexpected fixture info hash"
            with self.lock:
                self.connections += 1
                bits = bytearray((COUNT + 7) // 8)
                for i in self.allowed:
                    bits[i // 8] |= 0x80 >> (i % 8)
                client.sendall(handshake(self.info_hash, b"-MCREL1-012345678901") + frame(5, bits) + frame(1))
                self.clients.append(client)
            while True:
                length = struct.unpack("!I", receive(client, 4))[0]
                if length == 0:
                    continue
                message = receive(client, length)
                if message[0] == 6:
                    index, begin, size = struct.unpack("!III", message[1:])
                    assert index in self.allowed and size <= PIECE, ("invalid generated-fixture request", index, begin, size)
                    offset = index * PIECE + begin
                    with self.lock:
                        client.sendall(frame(7, struct.pack("!II", index, begin) + PAYLOAD[offset:offset + size]))
        except (EOFError, ConnectionError, OSError):
            pass
        except Exception as error:
            self.errors.append(error)
        finally:
            with self.lock:
                if client in self.clients:
                    self.clients.remove(client)
                self.disconnections += 1
            client.close()

    def allow(self, indexes):
        with self.lock:
            added = set(indexes) - self.allowed
            self.allowed.update(added)
            for client in self.clients:
                client.sendall(b"".join(frame(4, struct.pack("!I", i)) for i in sorted(added)))

    def close(self):
        self.sock.close()
        with self.lock:
            for client in self.clients:
                client.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--engine", type=Path, default=Path(__file__).resolve().parent.parent / ".build/torrent-engine/runtime/bin/aria2c")
    args = parser.parse_args()
    seeder = Seeder()
    class Tracker(BaseHTTPRequestHandler):
        def do_GET(self):
            data = fixtures.bencode({"interval": 2, "peers": socket.inet_aton("127.0.0.1") + struct.pack("!H", seeder.port)})
            self.send_response(200)
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def log_message(self, *_):
            pass
    tracker = ThreadingHTTPServer(("127.0.0.1", 0), Tracker)
    threading.Thread(target=tracker.serve_forever, daemon=True).start()
    info = {"name": "Generated", "private": 1, "piece length": PIECE,
            "files": [{"length": n, "path": [f"file{i}"]} for i, n in enumerate(SIZES)],
            "pieces": b"".join(hashlib.sha1(PAYLOAD[i:i + PIECE]).digest() for i in range(0, len(PAYLOAD), PIECE))}
    info_hash = hashlib.sha1(fixtures.bencode(info)).digest()
    metadata = fixtures.bencode({"announce": f"http://127.0.0.1:{tracker.server_port}/announce", "info": info})
    seeder.start(info_hash)
    process = None
    with tempfile.TemporaryDirectory(prefix="mycloud-live-cleanup-") as temporary:
        root = Path(temporary).resolve()
        payload = root / "payload"
        payload.mkdir()
        rpc_port, peer_port = fixtures.unused_port(), fixtures.unused_port()
        secret = secrets.token_hex(24)
        rpc_url = f"http://127.0.0.1:{rpc_port}/jsonrpc"
        def rpc(method, *params, allow_error=False):
            body = json.dumps({"jsonrpc": "2.0", "id": "fixture", "method": method if "." in method else "aria2." + method,
                               "params": ["token:" + secret, *params]}).encode()
            request = urllib.request.Request(rpc_url, data=body, headers={"Content-Type": "application/json"})
            try:
                response = urllib.request.urlopen(request, timeout=5)
            except urllib.error.HTTPError as error:
                response = error
            with response:
                result = json.load(response)
            if "error" in result:
                if allow_error:
                    return result["error"]
                raise AssertionError(result["error"])
            return result["result"]
        def start():
            nonlocal process
            command = [str(args.engine.resolve()), "--no-conf=true", "--enable-rpc=true", "--rpc-listen-all=false",
                       f"--rpc-listen-port={rpc_port}", f"--rpc-secret={secret}", f"--listen-port={peer_port}",
                       "--enable-dht=false", "--enable-dht6=false", "--enable-peer-exchange=false", "--bt-enable-lpd=false",
                       "--disable-ipv6=true", "--file-allocation=none", "--check-integrity=true", "--disk-cache=8M",
                       "--bt-remove-unselected-file=false", "--seed-time=5256000", "--seed-ratio=0",
                       "--max-download-limit=256K", "--bt-tracker-interval=1", "--auto-save-interval=1",
                       f"--log={root / 'engine.log'}", "--log-level=info",
                       "--console-log-level=error", "--summary-interval=0", "--enable-color=false"]
            process = subprocess.Popen(command, cwd=root, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            def ready():
                try:
                    return "aria2.releaseFiles" in rpc("system.listMethods")
                except (OSError, AssertionError):
                    if process.poll() is not None:
                        raise AssertionError("Fixture engine exited during startup")
                    return False
            wait_for(ready, "private fixture RPC")
        def add(selection="1-4"):
            return rpc("addTorrent", base64.b64encode(metadata).decode(), [], {"dir": str(payload), "select-file": selection})
        def status(gid):
            return rpc("tellStatus", gid, ["status", "files", "connections", "completedLength", "verifiedLength", "verifyIntegrityPending"])
        def complete(gid, index):
            entry = status(gid)["files"][index - 1]
            return entry["completedLength"] == entry["length"]
        def release(gid, indexes):
            return rpc("releaseFiles", gid, indexes, str(payload))
        def path(index):
            return payload / "Generated" / f"file{index - 1}"
        def cached_resumes():
            log = root / "engine.log"
            return log.read_text(errors="replace").count("Reusing verified torrent resume data") if log.exists() else 0
        def pause(gid):
            rpc("forcePause", gid)
            wait_for(lambda: status(gid)["status"] == "paused", "fixture pause checkpoint")
        def settled(gid):
            current = status(gid)
            return current["status"] == "active" and "verifiedLength" not in current and current.get("verifyIntegrityPending") != "true"
        def stop():
            nonlocal process
            if process and process.poll() is None:
                process.terminate()
                process.wait(timeout=15)
            process = None
        try:
            start()
            gid = add()
            wait_for(lambda: complete(gid, 1), "first generated file verified")
            assert not complete(gid, 2)
            # Clean pause and app restart reuse piece hashes without reading
            # the payload. Checks still run for legacy or changed local data.
            checkpoint = payload / "Generated.aria2"
            pause(gid)
            assert checkpoint.read_bytes()[-40:-32] == b"MCVR0001", "Verified resume trailer was not saved"
            count = cached_resumes()
            rpc("unpause", gid)
            wait_for(lambda: cached_resumes() == count + 1 and settled(gid), "cached pause/resume")
            count = cached_resumes()
            stop(); start(); gid = add()
            wait_for(lambda: cached_resumes() == count + 1 and settled(gid), "cached process restart")
            # A same-size edit with restored mtime must invalidate via ctime.
            pause(gid)
            before = path(1).stat()
            with path(1).open("r+b") as output:
                output.write(bytes([DATA[0][0] ^ 0xFF]))
            os.utime(path(1), ns=(before.st_atime_ns, before.st_mtime_ns))
            count = cached_resumes()
            rpc("unpause", gid)
            wait_for(lambda: settled(gid) and complete(gid, 1) and path(1).read_bytes() == DATA[0], "changed file checked and repaired")
            assert cached_resumes() == count, "Changed files must never use cached verification"
            pause(gid)
            path(1).unlink()
            count = cached_resumes()
            rpc("unpause", gid)
            wait_for(lambda: settled(gid) and path(1).exists() and path(1).read_bytes() == DATA[0], "missing file checked and repaired")
            assert cached_resumes() == count
            for invalidation in ["legacy", "damaged-cache", "damaged-bitfield"]:
                pause(gid)
                saved = bytearray(checkpoint.read_bytes())
                assert saved[-40:-32] == b"MCVR0001"
                if invalidation == "legacy":
                    saved = saved[:-40]
                elif invalidation == "damaged-cache":
                    saved[-1] ^= 0xFF
                else:
                    saved[54] ^= 0x80  # First verified piece, after v1 BT header.
                checkpoint.write_bytes(saved)
                count = cached_resumes()
                rpc("unpause", gid)
                wait_for(lambda: settled(gid) and complete(gid, 1), invalidation + " fallback")
                assert cached_resumes() == count, invalidation + " must fall back to hashing"
                assert path(1).read_bytes() == DATA[0]
            print("PASS verified resume cache: pause/restart skip hashing; same-size edits, missing files, old checkpoints and damaged cache/bitfield recheck safely", flush=True)
            assert release(gid, [1]) == [] and path(1).exists(), "Shared unfinished neighbour must pin file"
            assert rpc("releaseFiles", gid, [0], str(payload), allow_error=True)
            assert rpc("releaseFiles", gid, [1], str(root), allow_error=True)
            seeder.allow([2])
            wait_for(lambda: complete(gid, 2), "shared neighbour verified")
            connections = seeder.connections
            disconnected = seeder.disconnections
            # A symlink must not authorize deletion of anything outside payload.
            original = path(1).with_suffix(".held")
            path(1).rename(original)
            outside = root / "outside-fixture"
            outside.write_bytes(b"untouched")
            path(1).symlink_to(outside)
            assert release(gid, [1]) == [] and outside.read_bytes() == b"untouched"
            path(1).unlink()
            original.rename(path(1))
            before = sum(p.stat().st_blocks * 512 for p in (payload / "Generated").iterdir())
            assert release(gid, [1]) == [1] and not path(1).exists()
            after = sum(p.stat().st_blocks * 512 for p in (payload / "Generated").iterdir())
            assert after < before, "Allocated blocks must actually leave the payload"
            assert release(gid, [1]) == [1], "Retry after a lost reply must be idempotent"
            assert release(gid, [3]) == [], "Incomplete files must not be released"
            assert hashlib.sha256(path(2).read_bytes()).digest() == hashlib.sha256(DATA[1]).digest()
            # Newly handshaked peers see only pieces that can still be read.
            with socket.create_connection(("127.0.0.1", peer_port), timeout=10) as probe:
                probe.settimeout(10)
                probe.sendall(handshake(info_hash, b"-MCREL2-012345678901"))
                assert receive(probe, 68)[28:48] == info_hash
                saw_bits = False
                while not saw_bits:
                    length = struct.unpack("!I", receive(probe, 4))[0]
                    message = receive(probe, length)
                    if message and message[0] == 5:
                        assert message[1] & 0xC0 == 0 and message[1] & 0x20, "Released pieces were advertised"
                        saw_bits = True
                probe.sendall(frame(6, struct.pack("!III", 0, 0, PIECE)))
                while True:
                    length = struct.unpack("!I", receive(probe, 4))[0]
                    message = receive(probe, length)
                    if message and message[0] == 16:
                        assert struct.unpack("!III", message[1:]) == (0, 0, PIECE)
                        break
                    assert not message or message[0] != 7, "Released data was seeded"
            seeder.allow(range(COUNT))
            wait_for(lambda: int(status(gid)["completedLength"]) > 8 * PIECE, "same peer continues downloading")
            assert status(gid)["status"] == "active" and not path(1).exists()
            assert seeder.connections == connections and seeder.disconnections == disconnected
            assert not seeder.errors, repr(seeder.errors)
            print("PASS live engine cleanup: shared/incomplete files protected, blocks reclaimed, same peer/socket continues downloading, unavailable pieces masked/rejected", flush=True)
            # Exercise a fixture-only restart: released boundary bytes may need
            # fetching again; receipt-selected files must still hash correctly.
            count = cached_resumes()
            stop()
            start()
            gid = add("2-4")
            wait_for(lambda: cached_resumes() == count + 1, "cached restart with released pieces masked")
            wait_for(lambda: all(complete(gid, i) for i in [2, 3, 4]), "resume after released boundary", seconds=60)
            for index in [2, 3, 4]:
                assert hashlib.sha256(path(index).read_bytes()).digest() == hashlib.sha256(DATA[index - 1]).digest()
            if path(1).exists():
                assert release(gid, [1]) == [1] and not path(1).exists(), "Recreated, unselected boundary stub must be reclaimable"
            print("PASS cached restart after cleanup: released pieces excluded, remaining generated files resume and match SHA-256", flush=True)
        finally:
            stop()
            tracker.shutdown()
            tracker.server_close()
            seeder.close()


if __name__ == "__main__":
    main()
